// Splits a bill (in agorot, a whole number) between people by weights.
function parseWeight(w) {
  const s = String(w);
  const [mantissa, expStr] = s.split(/[eE]/);
  const exp = expStr ? parseInt(expStr, 10) : 0;
  const [intPart, fracPart = ""] = mantissa.split(".");
  const digits = (intPart + fracPart).replace(/^0+/, "") || "0";
  return { digits: BigInt(digits), scale: fracPart.length - exp };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => typeof w !== "number" || !Number.isFinite(w) || !(w > 0))) {
    throw new Error("bad weights");
  }

  const parsed = weights.map(parseWeight);
  const maxScale = Math.max(0, ...parsed.map((p) => p.scale));
  const intWeights = parsed.map((p) => p.digits * 10n ** BigInt(maxScale - p.scale));
  const sum = intWeights.reduce((a, b) => a + b, 0n);
  const bigTotal = BigInt(total);

  const floors = [];
  const remainders = [];
  let floorSum = 0n;

  for (let i = 0; i < intWeights.length; i++) {
    const num = bigTotal * intWeights[i];
    const f = num / sum;
    const r = num % sum;
    floors.push(Number(f));
    floorSum += f;
    remainders.push({ index: i, rem: r });
  }

  let leftover = Number(bigTotal - floorSum);
  remainders.sort((a, b) => (b.rem > a.rem ? 1 : b.rem < a.rem ? -1 : a.index - b.index));

  for (let i = 0; i < leftover; i++) {
    floors[remainders[i].index] += 1;
  }

  return floors;
}

module.exports = { splitBill };
