// Floating-point weights (0.1 + 0.2 !== 0.30000000000000004 issue avoided)
assert.deepStrictEqual(splitBill(30, [0.1, 0.2]), [10, 20]);
assert.deepStrictEqual(splitBill(100, [0.1, 0.2]), [33, 67]);
assert.deepStrictEqual(splitBill(100, [0.1, 0.1, 0.1]), [34, 33, 33]);

// Zero total and single person
assert.deepStrictEqual(splitBill(0, [1, 2, 3]), [0, 0, 0]);
assert.deepStrictEqual(splitBill(57, [42]), [57]);

// Tie-breaking by order when fractional parts are equal
assert.deepStrictEqual(splitBill(1, [1, 1, 1, 1]), [1, 0, 0, 0]);
assert.deepStrictEqual(splitBill(2, [1, 2, 1]), [1, 1, 0]); // exact: 0.5, 1.0, 0.5 -> tie between index 0 and 2

