const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  const dStart = parseTime(dayStart);
  const dEnd = parseTime(dayEnd);
  if (dEnd <= dStart) {
    throw new Error("dayEnd must be after dayStart");
  }

  const parsedBusy = busy.map(parseRange);

  const clamped = [];
  for (const r of parsedBusy) {
    const start = Math.max(r.start, dStart);
    const end = Math.min(r.end, dEnd);
    if (start < end) {
      clamped.push({ start, end });
    }
  }

  clamped.sort((a, b) => a.start - b.start || a.end - b.end);

  const merged = [];
  for (const r of clamped) {
    if (merged.length === 0 || merged[merged.length - 1].end < r.start) {
      merged.push({ ...r });
    } else {
      merged[merged.length - 1].end = Math.max(merged[merged.length - 1].end, r.end);
    }
  }

  const slots = [];
  let cursor = dStart;
  for (const r of merged) {
    if (r.start - cursor >= minLen) {
      slots.push(`${formatMinutes(cursor)}-${formatMinutes(r.start)}`);
    }
    cursor = r.end;
  }
  if (dEnd - cursor >= minLen) {
    slots.push(`${formatMinutes(cursor)}-${formatMinutes(dEnd)}`);
  }

  return slots;
}

module.exports = { freeSlots };
