// Splits a bill (in agorot, a whole number) between people by weights.
function toExactIntWeights(weights) {
  let maxExp = 0;
  const parts = weights.map((w) => {
    const s = w.toString().toLowerCase();
    const [mantissa, expPart] = s.split("e");
    const exp = expPart ? parseInt(expPart, 10) : 0;
    const [intPart, fracPart = ""] = mantissa.split(".");
    const decimals = fracPart.length - exp;
    if (decimals > maxExp) maxExp = decimals;
    return { digits: intPart + fracPart, decimals };
  });

  return parts.map(({ digits, decimals }) => {
    const pad = maxExp - decimals;
    return BigInt(digits + "0".repeat(pad));
  });
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => typeof w !== "number" || !Number.isFinite(w) || !(w > 0))) {
    throw new Error("bad weights");
  }

  const bigTotal = BigInt(total);
  const intWeights = toExactIntWeights(weights);
  const sum = intWeights.reduce((a, b) => a + b, 0n);

  const shares = [];
  const remainders = [];
  let distributed = 0n;

  for (let i = 0; i < intWeights.length; i++) {
    const num = bigTotal * intWeights[i];
    const flo = num / sum;
    const rem = num % sum;
    shares.push(Number(flo));
    remainders.push({ index: i, rem });
    distributed += flo;
  }

  let leftover = Number(bigTotal - distributed);
  remainders.sort((a, b) => (b.rem > a.rem ? 1 : b.rem < a.rem ? -1 : a.index - b.index));

  for (let i = 0; i < leftover; i++) {
    shares[remainders[i].index] += 1;
  }

  return shares;
}

module.exports = { splitBill };
