const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) {
    throw new Error("dayEnd must be after dayStart");
  }

  const parsedBusy = busy.map(parseRange);
  const clampedBusy = parsedBusy
    .map((r) => ({
      start: Math.max(start, r.start),
      end: Math.min(end, r.end),
    }))
    .filter((r) => r.end > r.start)
    .sort((a, b) => a.start - b.start || a.end - b.end);

  const merged = [];
  for (const r of clampedBusy) {
    if (merged.length === 0 || r.start > merged[merged.length - 1].end) {
      merged.push({ ...r });
    } else {
      merged[merged.length - 1].end = Math.max(merged[merged.length - 1].end, r.end);
    }
  }

  const slots = [];
  let cursor = start;
  for (const r of merged) {
    if (r.start - cursor >= minLen && r.start > cursor) {
      slots.push(`${formatMinutes(cursor)}-${formatMinutes(r.start)}`);
    }
    cursor = Math.max(cursor, r.end);
  }
  if (end - cursor >= minLen && end > cursor) {
    slots.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return slots;
}

module.exports = { freeSlots };
